import{_ as e,o as a,c as d,a3 as o}from"./chunks/framework.DAK02U1-.js";const g=JSON.parse('{"title":"配置参考","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"配置参考 | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/catter/guide/configuration"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/catter/guide/configuration"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/catter/guide/configuration"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/catter/guide/configuration"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/catter/guide/configuration"}]]},"headers":[],"relativePath":"zh/catter/guide/configuration.md","filePath":"zh/catter/guide/configuration.md","lastUpdated":1792915797000}'),i={name:"zh/catter/guide/configuration.md"};function r(c,t,n,s,h,l){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="配置参考" tabindex="-1">配置参考 <a class="header-anchor" href="#配置参考" aria-label="Permalink to &quot;配置参考&quot;">​</a></h1><h2 id="catter-命令行" tabindex="-1">catter 命令行 <a class="header-anchor" href="#catter-命令行" aria-label="Permalink to &quot;catter 命令行&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>catter [options] [&lt;built-in&gt; [built-in options]] -- &lt;build-command&gt;</span></span></code></pre></div><p>一次运行可以使用一个内置功能、一个或多个 <a href="./../scripting/handlers">handler</a>，或两者兼用。</p><h3 id="选项" tabindex="-1">选项 <a class="header-anchor" href="#选项" aria-label="Permalink to &quot;选项&quot;">​</a></h3><table tabindex="0"><thead><tr><th>选项</th><th>说明</th><th>默认值</th></tr></thead><tbody><tr><td><code>-m, --mode &lt;mode&gt;</code></td><td>runtime 模式：<code>inject</code> 运行构建命令并拦截它的进程；<code>replay</code> 回放一次录制的构建，以其事件文件代替构建命令。</td><td><code>inject</code></td></tr><tr><td><code>-d, --dir &lt;path&gt;</code></td><td>目标进程的工作目录。</td><td>当前目录</td></tr><tr><td><code>--handler &lt;command&gt;</code></td><td>由 catter 启动的 handler；可多次指定。见 <a href="./../scripting/handlers">Handler</a>。</td><td></td></tr><tr><td><code>--connect &lt;host:port&gt;</code></td><td>在该地址监听的 handler；可多次指定。见 <a href="./../scripting/handlers">Handler</a>。</td><td></td></tr><tr><td><code>--allow-remote</code></td><td>允许 <code>--connect</code> 连接其他机器上的 handler。</td><td></td></tr><tr><td><code>--handler-timeout &lt;seconds&gt;</code></td><td>catter 等待 handler 应答、以及会话结束后等待它退出的时长；<code>0</code> 表示一直等下去。</td><td><code>60</code></td></tr><tr><td><code>-h, --help</code></td><td>显示帮助信息。</td><td></td></tr></tbody></table><h3 id="数据目录" tabindex="-1">数据目录 <a class="header-anchor" href="#数据目录" aria-label="Permalink to &quot;数据目录&quot;">​</a></h3><p>catter 把日志和每个运行中会话的套接字放在 <code>$HOME/.catter</code>（Linux、macOS）或 <code>%LOCALAPPDATA%\\catter</code>（Windows）。设置了环境变量 <code>CATTER_HOME</code> 时，改用它指定的目录（须为绝对路径）。</p><h3 id="内置功能" tabindex="-1">内置功能 <a class="header-anchor" href="#内置功能" aria-label="Permalink to &quot;内置功能&quot;">​</a></h3><p>内置功能直接用名字指定，写在它的选项之前：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">catter</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [built-in </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">options]</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">build-comman</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>内置功能有：</p><table tabindex="0"><thead><tr><th>名称</th><th>说明</th></tr></thead><tbody><tr><td><code>cdb</code></td><td>生成 <code>compile_commands.json</code></td></tr><tr><td><code>cmd-tree</code></td><td>展示构建命令树</td></tr><tr><td><code>target-tree</code></td><td>展示构建目标树</td></tr><tr><td><code>inspect</code></td><td>展示 catter 如何分析一条命令（不运行它）</td></tr></tbody></table><h2 id="catter-proxy-命令行" tabindex="-1">catter-proxy 命令行 <a class="header-anchor" href="#catter-proxy-命令行" aria-label="Permalink to &quot;catter-proxy 命令行&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>catter-proxy</code> 是内部组件，由 catter 自动调用，不需要用户直接使用。</p></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>catter-proxy [options] -- &lt;command&gt;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>选项</th><th>说明</th></tr></thead><tbody><tr><td><code>-p &lt;id&gt;</code></td><td>用于 IPC 会话的父进程 ID</td></tr><tr><td><code>&lt;executable&gt;</code></td><td>已解析的可执行文件路径</td></tr></tbody></table><h2 id="环境变量" tabindex="-1">环境变量 <a class="header-anchor" href="#环境变量" aria-label="Permalink to &quot;环境变量&quot;">​</a></h2><p>以下环境变量由 catter 在运行时自动设置，此处仅作参考，无需手动配置。</p><h3 id="unix-linux-macos" tabindex="-1">Unix（Linux / macOS） <a class="header-anchor" href="#unix-linux-macos" aria-label="Permalink to &quot;Unix（Linux / macOS）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变量</th><th>用途</th></tr></thead><tbody><tr><td><code>__key_catter_proxy_path_v1</code></td><td><code>catter-proxy</code> 可执行文件的路径</td></tr><tr><td><code>__key_catter_command_id_v1</code></td><td>IPC 命令标识符</td></tr><tr><td><code>LD_PRELOAD</code>（Linux）</td><td>注入 catter 钩子共享库</td></tr><tr><td><code>DYLD_INSERT_LIBRARIES</code>（macOS）</td><td>注入 catter 钩子共享库</td></tr></tbody></table><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变量</th><th>用途</th></tr></thead><tbody><tr><td><code>CATTER_IPC_ID</code></td><td>IPC 会话标识符</td></tr><tr><td><code>CATTER_PROXY_PATH</code></td><td><code>catter-proxy</code> 可执行文件的路径</td></tr></tbody></table>',23)])])}const u=e(i,[["render",r]]);export{g as __pageData,u as default};
